type IFamilyDefOptions = {
  readonly maxSize?: number // 默认 4096，定义强缓存上限
  readonly debugLabel?: string // 默认 'family' / 'derived-family'
}

type IFamilyDef<K, T, D = IAtomDefinition<T>> = {
  (key: K): D
  readonly size: number
  forget(key: K): boolean
  clear(): void
