function familyDef<K extends IFamilyKey, T>(
  initial: (key: K) => T,
  options?: IFamilyDefOptions
): IFamilyDef<K, T, IWritableAtomDefinition<T>>

function derivedFamilyDef<K extends IFamilyKey, T>(
  read: (key: K) => (get: IAtomGet) => T,
  options?: IFamilyDefOptions
): IFamilyDef<K, T>

